/* Deterministic advected cloud/smoke billboards. Paths are normalized in the viewport. */
export const fract=x=>x-Math.floor(x);
const clamp=x=>Math.max(0,Math.min(1,x));
export function hash(n,seed=1){return fract(Math.sin(n*127.1+seed*311.7)*43758.5453123)}
export function sampleFlowPath(points,t){points=Array.isArray(points)&&points.length>1?points:[[0,.5],[1,.5]];const lengths=[],total=points.slice(1).reduce((sum,p,i)=>{const l=Math.hypot(p[0]-points[i][0],p[1]-points[i][1]);lengths.push(l);return sum+l},0);let distance=clamp(t)*total;for(let i=0;i<lengths.length;i++){if(distance<=lengths[i]||i===lengths.length-1){const q=lengths[i]?clamp(distance/lengths[i]):0;return [points[i][0]+(points[i+1][0]-points[i][0])*q,points[i][1]+(points[i+1][1]-points[i][1])*q]}distance-=lengths[i]}return points[0]}
export function atmosphereParticle(i,time,p){const seed=Number(p.seed)||1,speed=Number(p.speed)||0,life=fract(hash(i,seed)+time*speed/180),point=sampleFlowPath(p.path,life),thickness=(p.thickness??50)/100,turbulence=(p.turbulence??35)/100;return {x:point[0]*960+(hash(i+100,seed)-.5)*80*turbulence+Math.sin(time*.6+i)*14*turbulence,y:point[1]*540+(hash(i+200,seed)-.5)*thickness*190+Math.sin(time*.7+i*.9)*15*turbulence,life,alpha:Math.sin(life*Math.PI)*(.3+hash(i+300,seed)*.7),radius:(45+hash(i+400,seed)*90)*(p.scale??1),rotation:hash(i+500,seed)*6.28+time*.02}}
export function createAtmosphere(){const cache=new Map();function texture(color){if(cache.has(color))return cache.get(color);const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');for(let i=0;i<32;i++){const px=128+(hash(i,13)-.5)*125,py=128+(hash(i,17)-.5)*90,r=32+hash(i,29)*45,g=x.createRadialGradient(px,py,0,px,py,r);g.addColorStop(0,color+'38');g.addColorStop(.5,color+'22');g.addColorStop(1,color+'00');x.fillStyle=g;x.fillRect(px-r,py-r,r*2,r*2)}if(cache.size>12)cache.delete(cache.keys().next().value);cache.set(color,c);return c}return {paint(ctx,time,p={}){const density=Math.max(0,Math.min(100,p.density??50));if(!density||p.visible===false)return;const image=texture(/^#[0-9a-f]{6}$/i.test(p.color)?p.color:'#dce0db'),count=Math.round(12+density*.85);ctx.save();for(let i=0;i<count;i++){const v=atmosphereParticle(i,time,p);ctx.save();ctx.globalAlpha=v.alpha*density/100*(p.opacity??.75);ctx.translate(v.x,v.y);ctx.rotate(v.rotation);ctx.scale(1,Math.max(.15,(p.thickness??50)/65));ctx.drawImage(image,-v.radius,-v.radius,v.radius*2,v.radius*2);ctx.restore()}ctx.restore()}}}
